{"content": "import sys\np = \"/sessions/hopeful-awesome-curie/mnt/2hao-analyst/pipeline/iron_gate.py\"\nt = open(p).read()\n\nif \"self._check_methodology_compliance\" in t:\n    print(\"already patched\")\n    sys.exit(0)\n\n# Add to _check_funcs\nt = t.replace(\n    \"self._check_source_reliability,\",\n    \"self._check_source_reliability,\\n            self._check_methodology_compliance,\"\n)\n\n# Add method definition\nmethod_def = '''\n    def _check_methodology_compliance(self):\n        \"\"\"R96: 方法论合规检查。\"\"\"\n        from pipeline.checks.base import GateCheckResult\n        from pipeline.checks.methodology_compliance import check_methodology_compliance\n        r = check_methodology_compliance(self.report_text or \"\", self.report_type or \"\")\n        det = \"; \".join(r[\"issues\"][:3]) if r[\"issues\"] else \"无\"\n        return GateCheckResult(\"methodology_compliance\", r[\"passed\"], r[\"score\"], det, severity=\"warning\")\n\n    def _run_critic_agent'''\n\nt = t.replace(\"def _run_critic_agent\", method_def)\n\nopen(p, \"w\").write(t)\nprint(\"patched successfully\")\nprint(f\"occurrences: {t.count('methodology_compliance')}\")", "file_path": "{\"file_path\": \"D:/2hao-analyst/scripts/patch_compliance.py\"}"}